use std::{sync::Arc, time::{Duration, Instant}};
use volna_core::{App, Command, Instant as UiInstant, table::{TableCommand, columns::TransactionColumn}, testing::{a_all, complete_pending}};
use volna_trace::{session::LocalSession, data::Member};
use vtr::{Recorder, Value, Writer, SourceOptions, Status};
fn main() {
    for depth in [8, 16, 20] {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(format!("sort-{depth}.vtr"));
        let mut writer = Writer::create(&path).unwrap();
        let key = writer.intern("description").unwrap();
        let mut id = writer.intern_value(Value::U64(1)).unwrap();
        for _ in 0..depth {id = writer.intern_value(Value::List(vec![Value::Ref(id); 2])).unwrap();}
        let source = writer.transactions::<()>(SourceOptions::new("instructions", None), "INSTRUCTION").unwrap();
        for time in 0..64 {
            let tx=writer.begin_at(source,time,&(),None).unwrap();
            writer.attribute(tx.owner(),key,Value::Ref(id)).unwrap();
            writer.end_at(tx,time+1,Status::Ok).unwrap();
        }
        writer.close().unwrap();
        let mut app=App::new();app.set_session(Arc::new(LocalSession::open(&path).unwrap()));
        app.handle(Command::OpenTable {selected:a_all(vec![Member::Generator(0)]), clicked:None});
        let panel=app.panels.focused_id();complete_pending(&mut app);
        let attribute=TransactionColumn::Attribute("attributes.description".into());
        app.handle(Command::Table(panel,TableCommand::ShowTransactionColumn(attribute.clone())));
        let table=app.panels.get(panel).unwrap().kind.table().unwrap();
        let index=(0..100).find(|&i| table.transaction_column(i)==Some(&attribute)).unwrap();
        assert_eq!(table.len(),64);
        let start=Instant::now();app.handle(Command::Table(panel,TableCommand::SortColumn(index)));
        loop {
            app.tick(UiInstant::now());
            let table=app.panels.get(panel).unwrap().kind.table().unwrap();
            assert!(table.query_error.is_none());
            if !table.querying() {break;}
            assert!(start.elapsed()<Duration::from_secs(20));
            std::thread::sleep(Duration::from_millis(1));
        }
        println!("nodes={} rows=64 file_bytes={} sort_ms={:.3}",depth+1,std::fs::metadata(&path).unwrap().len(),start.elapsed().as_secs_f64()*1000.0);
    }
}

