use std::{hint::black_box, sync::Arc, time::Instant};
use volna_trace::data::transactions::AttributeValue;
fn main() {
    for depth in [8, 16, 22] {
        let mut value = AttributeValue::Shared(Arc::new(AttributeValue::U64(u64::MAX)));
        for _ in 0..depth {
            value = AttributeValue::Shared(Arc::new(AttributeValue::List(vec![value.clone(), value])));
        }
        let copy = value.clone();
        let start = Instant::now();
        assert!(black_box(&value) == black_box(&copy));
        println!("graph_nodes={} equality_ms={:.3}", depth + 1, start.elapsed().as_secs_f64() * 1000.0);
    }
}

